// Parse the S&OP upload payload from Django.
// Supports chunked uploads for large files:
//   action='replace' (chunk 0): clear tab then append
//   action='append'  (chunk 1+): append only (no clear)

const input = $input.first().json;
const tabName = input.tab_name || 'Forecast';
const headers = input.headers || [];
const rows    = input.rows || [];
const meta    = input._meta || {};
const action  = input.action || 'replace';

if (!rows.length) {
  throw new Error('No rows in payload for Forecast');
}

return [{
  json: {
    tab_name: tabName,
    report_key: input.report_key || 'sop_forecast',
    headers: headers,
    rows: rows,
    row_count: rows.length,
    action: action,
    chunk_index: input.chunk_index || 0,
    total_chunks: input.total_chunks || 1,
    total_rows: input.total_rows || rows.length,
    uploaded_by: meta.uploader || 'unknown',
    uploaded_at: meta.uploaded_at || new Date().toISOString(),
    original_file: meta.original_filename || '',
  }
}];

// Expand rows array into individual n8n items.
const data = $('Parse Payload').first().json;
const rows = data.rows || [];
const headers = data.headers || [];
if (!rows.length) return [];
return rows.map(row => {
  const ordered = {};
  if (headers.length > 0) {
    for (const h of headers) {
      ordered[h] = row[h] !== undefined ? row[h] : '';
    }
  } else {
    Object.assign(ordered, row);
  }
  return { json: ordered };
});

// Log summary
const data = $('Parse Payload').first().json;
const appended = $input.all().length;
return [{ json: {
  status: 'done',
  tab: 'Forecast',
  report_key: data.report_key,
  action: data.action,
  chunk: data.chunk_index + '/' + data.total_chunks,
  rows_written: appended,
  total_rows: data.total_rows,
  uploaded_by: data.uploaded_by,
  original_file: data.original_file,
}}];
